<!-- Generated by bildr from .bildr/modules/blog/pages/new-post.json. Editing this file detaches it from the editor; prefer overriding it from the root app/. -->
<script setup lang="ts">
definePageMeta({ name: 'posts-new', layout: 'main', layoutValues: { title: 'Write' } })

const { execute: createPost, pending: createPostPending, error: createPostError } = useCreatePost()
const form = reactive({ title: '', slug: '', body: '', published: false })
useSeoMeta({ title: 'New post' })

// Interaction "submit": run action Create post, then go to /posts/:slug.
const onFormSubmit = async () => {
  if (await createPost({ ...form })) await navigateTo({ name: 'posts-slug', params: { slug: form.slug } })
}

// Interaction "click": go to /.
const onCancelClick = async () => {
  await navigateTo('/')
}
</script>

<template>
  <div class="flex min-h-full flex-col">
    <BlogTip variant="collapsed" title="Writing tips" body="Keep the title short: the slug becomes the post's URL." class="mb-4 max-w-xl self-stretch" />
    <form class="flex max-w-xl flex-col gap-4 self-stretch" @submit.prevent="onFormSubmit">
      <h1 class="text-3xl font-semibold tracking-tight">New post</h1>
      <UFormField label="Title" name="title" required class="self-stretch">
        <UInput v-model="form.title" name="title" required maxlength="120" placeholder="A catchy title" class="w-full" />
      </UFormField>
      <UFormField label="Slug" name="slug" required class="self-stretch">
        <UInput v-model="form.slug" name="slug" required pattern="[a-z0-9\-]+" placeholder="my-first-post" class="w-full" />
      </UFormField>
      <UFormField label="Body" name="body" class="self-stretch">
        <UTextarea v-model="form.body" name="body" :rows="6" class="w-full" />
      </UFormField>
      <UCheckbox v-model="form.published" name="published" label="Publish now" />
      <p v-if="createPostError" class="text-sm whitespace-pre-line text-error">{{ createPostError }}</p>
      <div class="flex gap-2 self-stretch">
        <UButton type="submit" label="Create" icon="i-lucide-plus" :disabled="createPostPending" />
        <UButton label="Cancel" color="neutral" variant="ghost" @click="onCancelClick" />
      </div>
    </form>
  </div>
</template>
